mod cli {
    pub struct NativeExpertDaemonArgs {
        pub native_lib: std::path::PathBuf, pub snapshot: std::path::PathBuf,
        pub rank: u32, pub capacity: u32, pub device_budget_bytes: usize,
        pub max_frame_bytes: usize, pub listen: String,
    }
}
fn main() -> anyhow::Result<()> {
 use ds41rt_loader::{read_official_v41_catalog, OFFICIAL_V41_MODEL_ID};
 use ds41rt_ffi::{NativeLibrary, Ds41rtDeviceBuffer};
 use v41_experts::{ExpertWeights, ExpertLayer};
 use std::{path::Path,fs,time::Instant};
 let args: Vec<_> = std::env::args().collect();
 let lib=unsafe{NativeLibrary::load(&args[1])?};
 let catalog=read_official_v41_catalog(OFFICIAL_V41_MODEL_ID,Path::new("/model"))?;
 let mut weights=Vec::new();
 for layer in [0,1] {
  let geometry=ExpertLayer::Backbone{layer,rank:0};
  weights.push(ExpertWeights::load(&lib,&catalog,geometry,12*1024*1024*1024)?);
 }
 let budget=weights[0].execution_budget(80)?;
 assert!(budget.decode_scratch_bytes>0);
 assert!(weights[0].execution(80,budget.total()?-1).is_err());
 let mut wave=weights[0].execution(80,budget.total()?)?;
 let p1=wave.route_partials(1)?.ptr;
 let p80=wave.route_partials(80)?.ptr;
 assert_ne!(p1,p80);
 let compact=lib.v41_compact_reducer()?;
 let mut output=lib.alloc_device_buffer(80*5120*2)?;
 for (visit,layer) in [0,1,0].into_iter().enumerate() {
  wave.bind_layer(&weights[layer])?;
  for case in 0..2 {
   for (buffer,name) in wave.inputs().into_iter().zip(["hidden","ids","routing"]) {
    lib.copy_h2d(buffer,&fs::read(format!("/inputs/{case}-{name}.bin"))?)?;
   }
   for rows in [1,16,1,80,1] {
    let start=Instant::now();
    for _ in 0..10 {unsafe{wave.launch(rows,false)?;}}
    wave.synchronize()?;
    let us=start.elapsed().as_secs_f64()*1e6/10.;
    assert_eq!(wave.route_partials(1)?.ptr,p1);
    assert_eq!(wave.route_partials(80)?.ptr,p80);
    let partials=wave.route_partials(rows)?;
    let mut data=vec![0;partials.bytes];lib.copy_d2h(&mut data,partials)?;
    fs::write(format!("/output/v{visit}-c{case}-m{rows}-routes.bin"),data)?;
    unsafe{compact.compact(partials.ptr.cast(),output.ptr.cast(),rows,wave.stream())?;}
    wave.synchronize()?;
    let out=Ds41rtDeviceBuffer{bytes:rows as usize*5120*2,..output};
    let mut data=vec![0;out.bytes];lib.copy_d2h(&mut data,out)?;
    fs::write(format!("/output/v{visit}-c{case}-m{rows}-compact.bin"),data)?;
    println!("{{\"visit\":{visit},\"case\":{case},\"rows\":{rows},\"host_launch_and_drain_us\":{us}}}");
   }
  }
 }
 unsafe{wave.capture(1,false)?;}
 assert!(wave.bind_layer(&weights[1]).is_err());
 for case in 0..2 {
  for (buffer,name) in wave.inputs().into_iter().zip(["hidden","ids","routing"]) {
   lib.copy_h2d(buffer,&fs::read(format!("/inputs/{case}-{name}.bin"))?)?;
  }
  unsafe{wave.replay()?;}
  wave.synchronize()?;
  let partials=wave.route_partials(1)?;
  let mut data=vec![0;partials.bytes];lib.copy_d2h(&mut data,partials)?;
  assert_eq!(data,fs::read(format!("/output/v2-c{case}-m1-routes.bin"))?);
 }
 lib.free_device_buffer(&mut output)?;
 println!("PASS official layers, budget rejection, stable decode/prefill pointers, rebind and changed-input decode graph");
 Ok(())
}

